--
-- Name: update_ticket_message_timestamp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_ticket_message_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE "SupportTicket" SET "updatedAt" = clock_timestamp() WHERE "id" = NEW."ticketId";
    RETURN NEW;
END;
$$;


