--
-- Name: SupportTicket; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."SupportTicket" (
    id text DEFAULT ('T-'::text || (nextval('public.ticket_number_seq'::regclass))::text) NOT NULL,
    "customerId" text NOT NULL,
    subject character varying(200) NOT NULL,
    category public."TicketCategory" NOT NULL,
    description character varying(10000) NOT NULL,
    status public."TicketStatus" DEFAULT 'OPEN'::public."TicketStatus" NOT NULL,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "SupportTicket_description_check" CHECK ((length(btrim((description)::text)) > 0)),
    CONSTRAINT "SupportTicket_subject_check" CHECK ((length(btrim((subject)::text)) > 0))
);


